"""Public deterministic compatibility vector; these test keys are not secrets."""

from pathlib import Path
import tempfile
import unittest

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

from agy.local_ledger import LocalLedger
from agy.protocol import intent_digest, signing_bytes


class LegacyCompatibilityTests(unittest.TestCase):
    def test_v1_signed_events_keep_the_previous_published_head(self):
        # Generated by the previously published AGY implementation at 3919a53.
        keys = [Ed25519PrivateKey.from_private_bytes(bytes([i]) * 32) for i in (1, 2, 3)]

        def public_hex(key):
            return key.public_key().public_bytes(
                serialization.Encoding.Raw, serialization.PublicFormat.Raw).hex()

        policy = {"schema": "agy.local-policy.v1", "network_id": "agy-compat-test",
                  "agents": {"a": {"public_key": public_hex(keys[0]),
                                   "capabilities": ["read.report"]}},
                  "approvers": {"p": public_hex(keys[1])},
                  "verifiers": {"v": public_hex(keys[2])}}
        now = 1_750_000_000
        common = {"network_id": "agy-compat-test", "mission_id": "mission-1",
                  "issued_at": now - 1, "expires_at": now + 100}
        intent = {**common, "kind": "intent", "actor_id": "a", "nonce": "n1",
                  "capability": "read.report"}
        approval = {**common, "kind": "approval", "actor_id": "p", "nonce": "n2",
                    "intent_sha256": intent_digest(intent), "decision": "APPROVE"}
        self.assertEqual(intent_digest(intent),
                         "145dc7dfbd104c14ce89dc837982b6d181321b21c98913126aaca04a4f1da93c")
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "ledger.sqlite3"
            ledger = LocalLedger(path, policy, clock=lambda: now)
            for key, command in zip(keys, (intent, approval)):
                result = ledger.submit(command, key.sign(signing_bytes(command)).hex())
            self.assertEqual(result["head"],
                             "7eaa454eadf7bf8177071f71669448f65254fa0ee0792383f7f267ff45bea4d3")
            replay = LocalLedger(path, policy).verify(expected_head=result["head"])
            self.assertEqual(replay["missions"]["mission-1"]["state"], "AUTHORIZED")


if __name__ == "__main__":
    unittest.main()
